<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/lifecycle/prospects.php';
require_once dirname(__DIR__).'/crm/write.php';
require_once dirname(__DIR__).'/customer-settings.php';
function wf_readiness():array{
 $s=ocs_read();$p=ocs_active_policy($s);$draft=isset($s['draft_policy'])?ocs_policy($s['draft_policy']):null;
 $actions=[];$templates=crm_query("SELECT kind,revision_number,state,checksum,clauses_json FROM nd_lc_templates WHERE kind IN ('agreement','specification') ORDER BY kind,revision_number DESC")->fetchAll();foreach($templates as &$template){$template['package_source']=isset(json_decode($template['clauses_json'],true)['_package']);unset($template['clauses_json']);}unset($template);$profile=crm_query('SELECT reviewed FROM nd_lc_owner_profiles ORDER BY id DESC LIMIT 1')->fetchColumn();if(!$profile)$actions[]=['code'=>'owner_details','text'=>'Сохранить и проверить реквизиты исполнителя.','url'=>'/contract-settings.php'];foreach(['agreement'=>'договор','specification'=>'ТЗ'] as $kind=>$label){$approved=false;foreach($templates as $t)if($t['kind']===$kind&&$t['state']==='APPROVED'&&($t['package_source']||(config()['contract_package_required']??false)!==true))$approved=true;if(!$approved)$actions[]=['code'=>'template_'.$kind,'text'=>'Проверить и одобрить отдельный шаблон: '.$label.'.','url'=>'/documents.php?mode=owner#templates'];}
 if(!($s['max_miniapp_enabled']??false)||!$p||($s['max_miniapp_policy_hash']??'')!==$p['hash'])$actions[]=['code'=>'max_miniapp_platform','text'=>'Указать '+rtrim(config()['app_url'],'/').'/max.php в мини-приложении MAX и подтвердить настройку для точной политики.','url'=>'/client-settings.php'];
 if(!$p)$actions[]=['code'=>'policy','text'=>$draft?'Прочитать и одобрить точную версию политики и отдельного согласия '.$draft['version']:'Подготовить отдельную политику и согласие: указать проверенные основания, сроки и обработчиков.','url'=>'/client-settings.php'];
 if(!($s['prep_enabled']??false))$actions[]=['code'=>'preparation','text'=>'После одобрения документов открыть подготовку заказов.','url'=>'/client-settings.php'];
 if(!($s['document_exchange_enabled']??false))$actions[]=['code'=>'exchange','text'=>'Разрешить ограниченный обмен документами без регистрации.','url'=>'/client-settings.php'];
 if(!($s['portal_enabled']??$s['public_enabled']??false))$actions[]=['code'=>'portal','text'=>'Открыть кабинет по приглашениям после оплаты. Публичная регистрация остаётся закрытой.','url'=>'/client-settings.php'];
 return ['document_templates'=>$templates,'owner_details_reviewed'=>(bool)$profile,'policy'=>['approved'=>(bool)$p,'active_version'=>$p['version']??null,'active_hash'=>$p['hash']??null,'pending_version'=>$draft['version']??null,'pending_hash'=>$draft['hash']??null,'pending_state'=>$draft['state']??null],'mail'=>['verified'=>isset($s['mail_verified_at'],$s['mail']),'verified_at'=>$s['mail_verified_at']??null,'from'=>$s['mail']['from']??null,'repeat_verification_required'=>false],'capabilities'=>['public_inquiries'=>privacy_settings()['enabled'],'document_exchange'=>ps_enabled(),'paid_invitations'=>ca_enabled()&&ca_mail_ready(),'existing_client_login'=>ca_enabled(),'public_registration'=>false],'owner_actions'=>$actions];
}
function wf_start(array $d):array{
 return crm_idempotent('workflow/from-inquiry',$d,function()use($d){
  if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='020_inquiry_workflow'")->fetchColumn()!=='applied')crm_fail(503,'Маршрут обращения ещё не установлен.');
  $id=cc_id($d['lead_id']??null);$l=crm_query('SELECT * FROM nd_leads WHERE id=? FOR UPDATE',[$id])->fetch();if(!$l)crm_fail(404,'Обращение не найдено.');
  $old=crm_query('SELECT order_id,project_id FROM nd_lc_inquiry_orders WHERE lead_id=?',[$id])->fetch();if($old)return ['ok'=>true,'order_id'=>(int)$old['order_id'],'project_id'=>(int)$old['project_id'],'replayed'=>true];
  crm_version($d,$l);$cid=crm_query('SELECT customer_id FROM nd_lead_customers WHERE lead_id=?',[$id])->fetchColumn();$chosen=$d['customer_id']??null;if($chosen!==null)cc_id($chosen);if($cid&&$chosen!==null&&(int)$cid!==$chosen)crm_fail(409,'Обращение уже связано с другим клиентом.');
  if(!$cid){if($chosen!==null){$c=crm_record('customers',$chosen,true);if($c['status']!=='active')crm_fail(409,'Клиент архивирован.');$cid=$chosen;}else{$contact=trim($l['contact']);$data=['name'=>$l['name'],'notes'=>'Контакт из обращения: '.$contact];if(filter_var($contact,FILTER_VALIDATE_EMAIL))$data['email']=$contact;elseif(preg_match('~^https://max\.ru/u/[A-Za-z0-9_-]+$~D',$contact))$data['max_contact']=$contact;elseif(preg_match('/^@[A-Za-z][A-Za-z0-9_]{4,31}$/D',$contact))$data['telegram']=$contact;elseif(preg_match('/^(?:\+7|8)[0-9]{10}$/D',preg_replace('/[\s()\-]/','',$contact)))$data['phone']=$contact;else crm_fail(422,'Для создания клиента уточните контакт или выберите существующего клиента.');$cid=(int)crm_insert('customers',$data)['record']['id'];}crm_query('INSERT INTO nd_lead_customers(lead_id,customer_id) VALUES (?,?)',[$id,$cid]);}
  if(($d['order_id']??null)!==null){$o=crm_record('orders',cc_id($d['order_id']),true);if((int)$o['customer_id']!==(int)$cid||$o['archived_at']!==null)crm_fail(422,'Выберите действующий заказ этого клиента.');}else{$o=crm_insert('orders',['customer_id'=>(int)$cid,'title'=>mb_substr($l['service'].' — '.$l['name'],0,190),'total_amount'=>'0.00','currency'=>'RUB','notes'=>'Создан черновик из обращения. Цена ещё не согласована.'])['record'];}
  $p=crm_query('SELECT * FROM nd_projects WHERE order_id=? AND customer_id=? ORDER BY id LIMIT 1 FOR UPDATE',[$o['id'],$cid])->fetch();if(!$p)$p=crm_insert('projects',['customer_id'=>(int)$cid,'order_id'=>(int)$o['id'],'title'=>$o['title'],'description'=>$l['idea']])['record'];
  crm_query('INSERT INTO nd_lc_inquiry_orders(lead_id,order_id,project_id) VALUES (?,?,?)',[$id,$o['id'],$p['id']]);lc_flow_create(['type'=>'owner','id'=>1],['project_id'=>(int)$p['id']]);crm_event('projects',(int)$p['id'],'inquiry_workflow_started',['lead_id'=>$id,'customer_id'=>$cid]);return ['ok'=>true,'order_id'=>(int)$o['id'],'project_id'=>(int)$p['id'],'customer_id'=>(int)$cid,'price_approved'=>false];
 });
}
function wf_records(?int $order):array{
 $a=['type'=>'owner','id'=>1];$o=$order?crm_record('orders',$order):null;$p=$o?crm_query('SELECT project_id FROM nd_lc_order_flow WHERE order_id=?',[$order])->fetchColumn():null;if($o&&!$p)$p=crm_query('SELECT id FROM nd_projects WHERE order_id=? ORDER BY id LIMIT 1',[$order])->fetchColumn();
 $lists=[];$lists['customers']=crm_query("SELECT id,name AS label FROM nd_customers WHERE status='active' AND archived_at IS NULL ORDER BY name LIMIT 500")->fetchAll();
 $lists['orders']=crm_query('SELECT o.id,CONCAT(o.number,\' — \',o.title,\' · \',c.name) AS label,o.customer_id FROM nd_orders o JOIN nd_customers c ON c.id=o.customer_id WHERE o.archived_at IS NULL ORDER BY o.id DESC LIMIT 500')->fetchAll();
 $lists['projects']=crm_query('SELECT id,title AS label,order_id,customer_id FROM nd_projects WHERE archived_at IS NULL'.($order?' AND order_id=?':'').' ORDER BY id DESC LIMIT 500',$order?[$order]:[])->fetchAll();
 $lists['templates']=crm_query('SELECT id,CONCAT(title,\' · редакция \',revision_number,\' · \',state) AS label,kind,state FROM nd_lc_templates ORDER BY id DESC LIMIT 200')->fetchAll();
 $lists['documents']=crm_query('SELECT b.id,b.order_id,b.revision_id,t.kind,CONCAT(t.title,\' · редакция \',t.revision_number,\' · \',o.number,\' · \',b.state) AS label,b.state FROM nd_lc_document_bindings b JOIN nd_lc_templates t ON t.id=b.template_id JOIN nd_orders o ON o.id=b.order_id'.($order?' WHERE b.order_id=?':'').' ORDER BY b.id DESC LIMIT 500',$order?[$order]:[])->fetchAll();
 $lists['files']=crm_query('SELECT f.id,f.project_id,CONCAT(f.display_name,\' · \',p.title,\' · \',f.created_at) AS label FROM nd_cc_files f JOIN nd_projects p ON p.id=f.project_id WHERE f.archived_at IS NULL'.($p?' AND f.project_id=?':'').' ORDER BY f.id DESC LIMIT 500',$p?[$p]:[])->fetchAll();
 $lists['revisions']=crm_query('SELECT r.id,d.project_id,CONCAT(d.title,\' · редакция \',r.revision_number,\' · \',r.status) AS label FROM nd_cc_revisions r JOIN nd_cc_documents d ON d.id=r.document_id'.($p?' WHERE d.project_id=?':'').' ORDER BY r.id DESC LIMIT 500',$p?[$p]:[])->fetchAll();
 $lists['quotes']=crm_query('SELECT q.id,q.project_id,CONCAT(p.title,\' · расчёт, редакция \',q.revision_number,\' · \',q.state) AS label,q.state,q.calculation_json FROM nd_quotations q JOIN nd_projects p ON p.id=q.project_id'.($p?' WHERE q.project_id=?':'').' ORDER BY q.id DESC LIMIT 300',$p?[$p]:[])->fetchAll();
 foreach($lists['quotes'] as &$quote){$calc=json_decode($quote['calculation_json'],true);$quote['amount']=isset($calc['selling_minor'])?bill_decimal((int)$calc['selling_minor']):null;if($quote['amount']!==null)$quote['label'].=' · '.$quote['amount'].' руб.';unset($quote['calculation_json']);}unset($quote);
 $lists['stages']=crm_query('SELECT id,project_id,title AS label FROM nd_project_stages'.($p?' WHERE project_id=?':'').' ORDER BY position,id LIMIT 500',$p?[$p]:[])->fetchAll();
 $lists['accounts']=crm_query('SELECT a.id,a.customer_id,CONCAT(c.name,\' · \',a.email) AS label FROM nd_customer_accounts a JOIN nd_customers c ON c.id=a.customer_id'.($o?' WHERE a.customer_id=?':'').' ORDER BY a.id DESC LIMIT 300',$o?[$o['customer_id']]:[])->fetchAll();
 $lists['milestones']=crm_query('SELECT v.id,CONCAT(s.title,\' · версия \',v.revision_number,\' · \',v.state) AS label FROM nd_lc_milestone_versions v JOIN nd_project_stages s ON s.id=v.stage_id'.($order?' WHERE v.order_id=?':'').' ORDER BY v.id DESC LIMIT 300',$order?[$order]:[])->fetchAll();
 $lists['changes']=crm_query('SELECT id,CONCAT(\'Изменение к заказу \',order_id,\' · \',LEFT(request_body,120)) AS label FROM nd_lc_scope_changes'.($order?' WHERE order_id=?':'').' ORDER BY id DESC LIMIT 200',$order?[$order]:[])->fetchAll();
 $lists['claims']=crm_query('SELECT c.id,CONCAT(c.payer,\' · \',c.amount_minor/100,\' руб. · \',c.paid_at) AS label FROM nd_lc_payment_claims c JOIN nd_invoices i ON i.id=c.invoice_id'.($order?' WHERE i.order_id=?':'').' ORDER BY c.id DESC LIMIT 200',$order?[$order]:[])->fetchAll();
 $lists['payments']=crm_query('SELECT p.id,CONCAT(i.number,\' · поступление \',p.amount_minor/100,\' руб.\') AS label FROM nd_payment_attempts p JOIN nd_invoices i ON i.id=p.invoice_id'.($order?' WHERE i.order_id=?':'').' ORDER BY p.id DESC LIMIT 300',$order?[$order]:[])->fetchAll();
 $lists['catalog_templates']=crm_query('SELECT v.id,CONCAT(t.title,\' · редакция \',v.revision_number) AS label FROM nd_catalog_template_versions v JOIN nd_catalog_templates t ON t.id=v.template_id WHERE v.published_at IS NOT NULL AND t.state=\'PUBLISHED\' ORDER BY v.id DESC LIMIT 100')->fetchAll();
 $prefill=[];$profile=crm_query('SELECT data_json FROM nd_lc_owner_profiles ORDER BY id DESC LIMIT 1')->fetchColumn();if($profile){$d=json_decode($profile,true);foreach(['owner_name'=>'full_name','owner_inn'=>'inn','owner_address'=>'postal_address','owner_contact'=>'email','bank_name'=>'bank','bank_account'=>'account','bank_bik'=>'bik','bank_corr'=>'corr'] as $field=>$key)$prefill[$field]=$d[$key]??'';}
 if($o){$party=crm_query("SELECT data_json FROM nd_lc_customer_details WHERE order_id=? AND state='APPROVED' ORDER BY id DESC LIMIT 1",[$order])->fetchColumn();if($party){$d=json_decode($party,true);foreach(['client_name'=>'name','client_inn'=>'inn','client_type'=>'type','client_address'=>'address','client_contact'=>'email','client_authority'=>'authority'] as $field=>$key)$prefill[$field]=$d[$key]??'';}}
 return ['ok'=>true,'lists'=>$lists,'prefill'=>$prefill,'context'=>$o?['order_id'=>$order,'project_id'=>$p?(int)$p:null,'customer_id'=>(int)$o['customer_id'],'label'=>$o['number'].' — '.$o['title'],'order_version'=>(int)$o['version']]:null,'flow'=>$order&&crm_query('SELECT order_id FROM nd_lc_order_flow WHERE order_id=?',[$order])->fetchColumn()?lc_flow_detail($a,$order):null];
}

function wf_apply_price(array $d):array{return crm_idempotent('workflow/apply-approved-price',$d,function()use($d){$o=crm_record('orders',cc_id($d['order_id']??null),true);crm_version($d,$o);$q=pricing_detail(cc_id($d['quotation_id']??null));$p=crm_record('projects',(int)$q['project_id']);if((int)$p['order_id']!==(int)$o['id']||$q['state']!=='APPROVED'||!pricing_fresh($q)||($d['confirm']??false)!==true)crm_fail(409,'Выберите текущий одобренный расчёт этого заказа и подтвердите применение цены.');$value=bill_decimal((int)$q['calculation']['selling_minor']);$values=crm_values('orders',['total_amount'=>$value],$o);crm_query('UPDATE nd_orders SET total_amount=?,version=version+1 WHERE id=?',[$values['total_amount'],$o['id']]);crm_event('orders',(int)$o['id'],'approved_price_applied',$o);return ['ok'=>true,'order_id'=>(int)$o['id'],'price'=>$value];});}
